package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
/** Daily discovery with a grid fitted to actual viewport and accessible font size. */
final class RecommendationsView extends ScrollView {
 private final LinearLayout body,grid;private final TextView state;private final Button more;private int generation,type=-1,page,lastColumns;private boolean loading;private final java.util.Set<String> seen=new java.util.HashSet<>();private final java.util.List<JSONObject> catalog=new java.util.ArrayList<>();
 RecommendationsView(Context c){this(c,false);}
 RecommendationsView(Context c,boolean games){super(c);setVerticalScrollBarEnabled(false);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);int p=dp(16);body.setPadding(p,p,p,p);addView(body);body.addView(NativeSheet.text(c,"Descubra sua próxima aventura",26,0xfff5f0ff));Spinner kind=NativeSheet.options(c,new String[]{"Filmes","Séries","Animes"});if(!games)body.addView(kind);state=NativeSheet.text(c,"",13,0xffb8abd0);body.addView(state);grid=new LinearLayout(c);grid.setOrientation(LinearLayout.VERTICAL);body.addView(grid);more=new Button(c);more.setText("Mais sugestões");AppStyle.button(more,false);body.addView(more);more.setOnClickListener(v->load());if(games){type=3;generation++;load();}else kind.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,android.view.View v,int pos,long id){if(type==pos)return;type=pos;generation++;loading=false;page=0;seen.clear();catalog.clear();grid.removeAllViews();load();}public void onNothingSelected(AdapterView<?> p){}});}
 private int columns(){float width=getWidth()>0?getWidth()/getResources().getDisplayMetrics().density:getResources().getConfiguration().screenWidthDp;return ResponsivePolicy.columns(width-32,getResources().getConfiguration().fontScale);}
 @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);if(grid!=null&&w!=oldw&&columns()!=lastColumns){int y=getScrollY();post(()->{render();scrollTo(0,y);});}}
 private void render(){grid.removeAllViews();int columns=columns();lastColumns=columns;LinearLayout row=null;for(int i=0;i<catalog.size();i++){JSONObject x=catalog.get(i);final int target=type;if(i%columns==0){row=new LinearLayout(getContext());grid.addView(row);}LinearLayout tile=new LinearLayout(getContext());tile.setOrientation(LinearLayout.VERTICAL);tile.setPadding(dp(10),dp(10),dp(10),dp(10));tile.setBackground(AppStyle.shape(tile,0xff241d31,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,dp(10),i%columns<columns-1?dp(10):0,0);row.addView(tile,lp);ArtworkFrame art=new ArtworkFrame(getContext(),target==3?.65f:1.45f);tile.addView(art,new LinearLayout.LayoutParams(-1,-2));ImageView cover=new ImageView(getContext());cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setBackground(AppStyle.shape(cover,0xff32263f,12));cover.setClipToOutline(true);art.addView(cover,new FrameLayout.LayoutParams(-1,-1));AccountImageLoader.load(cover,x.optString("capa",""));TextView name=NativeSheet.text(getContext(),x.optString("nome"),14,0xfff1e8fc);name.setMaxLines(2);name.setMinLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(name);Button add=new Button(getContext());add.setText("+ Adicionar");AppStyle.button(add,false);tile.addView(add);add.setOnClickListener(v->{if(target==3)new AddGameDialog(getContext(),x,()->Toast.makeText(getContext(),"Jogo adicionado",Toast.LENGTH_SHORT).show());else new AddMediaDialog(getContext(),target,x,()->Toast.makeText(getContext(),"Título adicionado",Toast.LENGTH_SHORT).show());});}if(row!=null&&catalog.size()%columns!=0)for(int i=catalog.size()%columns;i<columns;i++)row.addView(new android.view.View(getContext()),new LinearLayout.LayoutParams(0,1,1));}
 private void load(){if(loading)return;loading=true;more.setEnabled(false);state.setText("Carregando sugestões…");int ticket=generation,target=type;new AccountRepository(getContext()).recommendations(target,page+1,(rows,error)->{if(ticket!=generation)return;loading=false;more.setEnabled(true);if(error!=null){state.setText(error);return;}page++;for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(x!=null&&seen.add(x.optString("nome")))catalog.add(x);}render();state.setText(seen.size()+" sugestões • seleção do dia");more.setVisibility(page<10?VISIBLE:GONE);});}
 private int dp(int n){return AppStyle.dp(this,n);}
}
